// 朴素二分，(n*log(m))
func searchMatrix(matrix [][]int, target int) bool {
	bin_search:= func(arr []int,target int)bool {
		l,r,mid:=0,len(arr),0
		for l<=r{
			mid = l+(r-l)/2
			if arr[mid]==target{
				return  true
			}else if arr[mid]<target{
				l = mid+1
			}else{
				r=mid-1
			}
		}
		return false
	}
	for _,row:=range matrix{
		if bin_search(row,target){
			return true
		}
	}
	return false
}
